// ============================================================
// WF8 — BATCH OPTIMIZATION ENGINE (scheduled)
// Computes optimization scores for EVERY provider in one pass,
// instead of one provider per live webhook request.
// Google Places enrichment (WF2) is intentionally skipped here —
// it's per-provider and request-scoped; the dashboard-read flow
// can still call WF2 live if it wants that layer on top.
// ============================================================
const allBookings = $input.all().map(r => r.json);
const now = new Date();
const today = now.toISOString().split('T')[0];
const maxDailyBookings = 4;       // default fallback, same as WF8 intake default
const allPossibleSlots = ['09:00','10:00','11:00','12:00','14:00','15:00','16:00','17:00'];

// ── Platform-wide average (for earning fairness comparisons) ──
const platformCompleted = allBookings.filter(b => b.status === 'completed');
const platformTotal = platformCompleted.reduce((sum, b) => sum + (parseInt(b.final_price_pkr || b.price_pkr) || 0), 0);
const platformAvg = platformCompleted.length > 0 ? Math.round(platformTotal / platformCompleted.length) : 1200;

// ── Distinct provider set: anyone who owns or was reassigned a booking ──
const providerIds = new Set();
allBookings.forEach(b => {
  if (b.provider_id) providerIds.add(b.provider_id);
  if (b.reassigned_to_provider_id) providerIds.add(b.reassigned_to_provider_id);
});

const results = [];

for (const myProviderId of providerIds) {
  const myOriginalBookings = allBookings.filter(b =>
    b.provider_id === myProviderId &&
    (!b.reassigned_to_provider_id || b.reassigned_to_provider_id !== myProviderId)
  );
  const reassignedToMe = allBookings.filter(b => b.reassigned_to_provider_id === myProviderId);
  const iLostBookings = myOriginalBookings.filter(b => b.status === 'rescheduled' && b.provider_action_locked);

  const allMyEarningBookings = [
    ...myOriginalBookings.filter(b => b.status === 'completed'),
    ...reassignedToMe.filter(b => b.status === 'completed')
  ];

  // Workload
  const confirmedToday = myOriginalBookings.filter(b =>
    b.booking_date === today && (b.status === 'confirmed' || b.status === 'in_progress') && !b.provider_action_locked
  ).concat(
    reassignedToMe.filter(b => b.booking_date === today && (b.status === 'confirmed' || b.status === 'in_progress'))
  );
  const utilizationRate = Math.round((confirmedToday.length / maxDailyBookings) * 100);
  const workloadStatus =
    utilizationRate >= 100 ? 'FULL' :
    utilizationRate >= 75  ? 'BUSY' :
    utilizationRate >= 50  ? 'MODERATE' : 'AVAILABLE';
  const bookedSlotsToday = confirmedToday.map(b => b.slot);
  const openSlotsToday = allPossibleSlots.filter(s => !bookedSlotsToday.includes(s));

  // Earnings
  const totalEarnings = allMyEarningBookings.reduce((sum, b) => sum + (parseInt(b.final_price_pkr || b.price_pkr) || 0), 0);
  const avgEarningPerJob = allMyEarningBookings.length > 0 ? Math.round(totalEarnings / allMyEarningBookings.length) : 0;
  const earningIndex = avgEarningPerJob > 0 ? parseFloat((avgEarningPerJob / platformAvg).toFixed(2)) : 1.0;
  const earningFairness = earningIndex >= 0.9 ? 'FAIR' : earningIndex >= 0.7 ? 'BELOW_AVERAGE' : 'LOW';

  // Reputation
  const ratedBookings = allMyEarningBookings.filter(b => b.customer_rating !== null && b.customer_rating !== undefined);
  const ratings = ratedBookings.map(b => parseFloat(b.customer_rating));
  const avgRating = ratings.length > 0 ? parseFloat((ratings.reduce((a, b) => a + b, 0) / ratings.length).toFixed(2)) : null;
  const flaggedCount = [...myOriginalBookings, ...reassignedToMe].filter(b => b.flagged_for_review === true).length;
  const reputationHealth =
    flaggedCount > 3 ? 'AT_RISK' :
    flaggedCount > 1 ? 'MONITOR' :
    avgRating === null ? 'NEW' :
    avgRating >= 4.5 ? 'EXCELLENT' :
    avgRating >= 3.5 ? 'GOOD' : 'NEEDS_IMPROVEMENT';

  // Cancellations
  const cancelledAll = myOriginalBookings.filter(b =>
    b.status === 'cancelled' || b.status === 'provider_cancelled' || b.status === 'no_show'
  );
  const totalBookings = myOriginalBookings.length;
  const cancellationRate = totalBookings > 0 ? parseFloat((cancelledAll.length / totalBookings).toFixed(2)) : 0;
  const cancellationStatus =
    cancellationRate > 0.20 ? 'HIGH_RISK' :
    cancellationRate > 0.10 ? 'WARNING' : 'GOOD';

  // Loyalty
  const emailCounts = {};
  allMyEarningBookings.forEach(b => { if (b.user_email) emailCounts[b.user_email] = (emailCounts[b.user_email] || 0) + 1; });
  const repeatCustomers = Object.entries(emailCounts).filter(([, c]) => c >= 2);

  // Demand forecast (platform-wide, same for every provider — computed once outside loop would be more efficient,
  // kept per-provider here for parity with the original per-request payload shape)
  const slotDemand = {};
  allPossibleSlots.forEach(s => { slotDemand[s] = 0; });
  allBookings.forEach(b => { if (b.slot && slotDemand[b.slot] !== undefined) slotDemand[b.slot]++; });
  const recommendedSlots = Object.entries(slotDemand).sort((a, b) => b[1] - a[1]).slice(0, 3)
    .map(([slot, count]) => ({ slot, demand_score: count, is_open_today: openSlotsToday.includes(slot) }));

  // Rate suggestion
  let rateSuggestion;
  if (earningFairness === 'LOW') {
    rateSuggestion = { suggested_base_rate: Math.round(platformAvg * 0.85), reason: 'Avg earning significantly below platform average.' };
  } else if (earningFairness === 'BELOW_AVERAGE') {
    rateSuggestion = { suggested_base_rate: Math.round(avgEarningPerJob * 1.1) || platformAvg, reason: 'Slightly below platform average.' };
  } else {
    rateSuggestion = { suggested_base_rate: null, reason: 'Rate is fair relative to platform average.' };
  }

  const tips = [
    utilizationRate < 50 ? `Only ${confirmedToday.length} slots filled today.` : null,
    earningFairness !== 'FAIR' ? `Avg earning PKR ${avgEarningPerJob} is below platform avg PKR ${platformAvg}.` : null,
    cancellationStatus !== 'GOOD' ? `Cancellation rate ${(cancellationRate*100).toFixed(0)}% is ${cancellationStatus}.` : null,
    repeatCustomers.length > 0 ? `${repeatCustomers.length} repeat customer(s) — consider a loyalty discount.` : null
  ].filter(Boolean);

  results.push({
    json: {
      provider_id: myProviderId,
      provider_name: (myOriginalBookings[0] || reassignedToMe[0] || {}).provider_name || myProviderId,
      computed_at: now.toISOString(),

      utilization_rate_pct: utilizationRate,
      workload_status: workloadStatus,
      slots_open_today: openSlotsToday,

      total_completed_jobs: allMyEarningBookings.length,
      total_earnings_pkr: totalEarnings,
      avg_per_job_pkr: avgEarningPerJob,
      platform_avg_pkr: platformAvg,
      earning_fairness: earningFairness,

      avg_rating: avgRating,
      reputation_health: reputationHealth,
      flagged_bookings: flaggedCount,

      cancellation_rate_pct: Math.round(cancellationRate * 100),
      cancellation_status: cancellationStatus,

      repeat_customers: repeatCustomers.length,
      recommended_slots: recommendedSlots,
      optimization_tips: tips,
      rate_optimization: rateSuggestion,

      raw: null // filled below after object is built, to embed the full record
    }
  });
}

// Embed the full record as `raw` for dashboard rendering without recomputation
results.forEach(r => { r.json.raw = { ...r.json }; });

return results;
